"""Chapter 5: the complex normative accounting (standard-direct-costing) = the information base of the budget. Table 26 of the book lists the business processes (operations) by the
stages of the financial cycle; every operation (a posting / an accounting procedure) = ONE task. Operations "during the budget period" run through the whole quarter (parallel bars),
operations "at the end of the budget period" start after the milestone "End of the budget period"."""
from wbs_kit import *

CA, CM, CS, CT, CC = 'r_cost_accountant', 'r_acc_materials', 'r_acc_settlements', 'r_tax_accountant', 'r_chief_accountant'


def op(code, title, anchor, who, when='in', note='', **kw):
    """an accounting operation: when='in' = during the budget period (a bar through the quarter, parallel); 'end' = at the end of the period; 'once' = a one-off decision"""
    if when == 'in':
        return T(code, title, anchor, 60, W(*who), note=note, at='2001-04-02', **kw)
    if when == 'end':
        return T(code, title, anchor, 4, W(*who), note=note, after=['MS.END'], **kw)
    return T(code, title, anchor, kw.pop('d', 3), W(*who), note=note, **kw)


